package com.mazkiplay.nusantara;
import android.app.*;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import android.content.*;import java.util.*;
public class NeuralActivity extends Activity{
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setBackgroundColor(Color.rgb(9,9,11));LinearLayout top=new LinearLayout(this);Button back=new Button(this);back.setText("←");back.setTextColor(Color.WHITE);top.addView(back,new LinearLayout.LayoutParams(60,60));TextView title=new TextView(this);title.setText("🧠 NEURAL NETWORK AGENT INSPECTOR\nLIVE SYNAPSE • TRANSFORMER MONITOR");title.setTextColor(Color.WHITE);title.setTextSize(14);title.setPadding(12,8,8,8);top.addView(title);r.addView(top);r.addView(new NetView(this),new LinearLayout.LayoutParams(-1,0,1));String[] s={"RESPONSE LATENCY    provider dependent","TOKENS / SEC        provider dependent","TEMPERATURE         0.4","CONTEXT             model dependent","AGENT STATE         ORCHESTRATOR READY","TOOLS               CHAT • MARKET • VISION • PDF"};for(String x:s){TextView t=new TextView(this);t.setText(x);t.setTextColor(Color.rgb(161,161,170));t.setTextSize(11);t.setPadding(14,7,14,7);r.addView(t);}setContentView(r);back.setOnClickListener(v->finish());}
 class NetView extends View{Paint p=new Paint(1);long tick;NetView(Context c){super(c);}protected void onDraw(Canvas c){c.drawColor(Color.rgb(24,24,27));float w=getWidth(),h=getHeight();float[][] n={{.15f,.25f},{.15f,.75f},{.5f,.18f},{.5f,.5f},{.5f,.82f},{.85f,.35f},{.85f,.65f}};p.setStrokeWidth(2);for(int i=0;i<n.length;i++)for(int j=i+1;j<n.length;j++)if(Math.abs(n[i][0]-n[j][0])<.55f){p.setColor(Color.rgb(55,55,62));c.drawLine(n[i][0]*w,n[i][1]*h,n[j][0]*w,n[j][1]*h,p);}for(int i=0;i<n.length;i++){p.setColor(i%2==0?Color.rgb(6,182,212):Color.rgb(16,185,129));c.drawCircle(n[i][0]*w,n[i][1]*h,7+(float)Math.sin((System.currentTimeMillis()*.006)+i)*2,p);}postInvalidateDelayed(50);}}
}